def bell_number(n):
    # Base case: B(0) = 1
    if n == 0:
        return 1

    # Initialize an array to store Bell numbers
    bell = [0] * (n + 1)
    bell[0] = 1

    # Compute Bell numbers using the recursive formula
    for i in range(1, n + 1):
        bell[i] = 0
        for k in range(i + 1):
            bell[i] += bell[k] if k == 0 else bell[k] * combin(k,i)

    return bell[n]

def combin(k,i):
    return factorial(i) // (factorial(i-k) * factorial(k))

def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

