def max_sum_increasing_subseq(arr, n, i, k):
    if k >= n or i >= n:
        return 0
    if i >= k:
        return 0

    # Create a prefix sum array
    prefix_sum = [0] * n
    for j in range(n):
        prefix_sum[j] = arr[j]

    # Create a dp array to store the maximum sum of increasing subsequence
    dp = [0] * n
    for j in range(n):
        current_max = 0
        for l in range(j):
            if arr[l] < arr[j]:
                current_max = max(current_max, dp[l])
        dp[j] = arr[j] + current_max

    # Update the maximum sum including the kth element
    max_sum = 0
    for j in range(i + 1):
        if arr[j] <= arr[k]:
            max_sum = max(max_sum, dp[j])

    return max_sum

